use split_decls_genesis :: ourprelude :: * ; #[doc = " Xous passes a pointer to the parameter block as the second argument."] #[doc = " This is used for passing flags such as environment variables. The"] #[doc = " format of the argument block is:"] #[doc = ""] #[doc = " #[repr(C)]"] #[doc = " struct BlockHeader {"] #[doc = "     /// Magic number that identifies this block. Must be printable ASCII."] #[doc = "     magic: [u8; 4],"] #[doc = ""] #[doc = "     /// The size of the data block. Does not include this header. May be 0."] #[doc = "     size: u32,"] #[doc = ""] #[doc = "     /// The contents of this block. Varies depending on the block type."] #[doc = "     data: [u8; 0],"] #[doc = " }"] #[doc = ""] #[doc = " There is a BlockHeader at the start that has magic `AppP`, and the data"] #[doc = " that follows is the number of blocks present:"] #[doc = ""] #[doc = " #[repr(C)]"] #[doc = " struct ApplicationParameters {"] #[doc = "     magic: b\"AppP\","] #[doc = "     size: 4u32,"] #[doc = ""] #[doc = "     /// The size of the entire application slice, in bytes, including all headers"] #[doc = "     length: u32,"] #[doc = ""] #[doc = "     /// Number of application parameters present. Must be at least 1 (this block)"] #[doc = "     entries: (parameter_count as u32).to_bytes_le(),"] #[doc = " }"] #[doc = ""] #[doc = " #[repr(C)]"] #[doc = " struct EnvironmentBlock {"] #[doc = "     magic: b\"EnvB\","] #[doc = ""] #[doc = "     /// Total number of bytes, excluding this header"] #[doc = "     size: 2+data.len(),"] #[doc = ""] #[doc = "     /// The number of environment variables"] #[doc = "     count: u16,"] #[doc = ""] #[doc = "     /// Environment variable iteration"] #[doc = "     data: [u8; 0],"] #[doc = " }"] #[doc = ""] #[doc = " Environment variables are present in an `EnvB` block. The `data` section is"] #[doc = " a sequence of bytes of the form:"] #[doc = ""] #[doc = "      (u16 /* key_len */; [0u8; key_len as usize] /* key */,"] #[doc = "       u16 /* val_len */ [0u8; val_len as usize])"] #[doc = ""] #[doc = " #[repr(C)]"] #[doc = " struct ArgumentList {"] #[doc = "     magic: b\"ArgL\","] #[doc = ""] #[doc = "     /// Total number of bytes, excluding this header"] #[doc = "     size: 2+data.len(),"] #[doc = ""] #[doc = "     /// The number of arguments variables"] #[doc = "     count: u16,"] #[doc = ""] #[doc = "     /// Argument variable iteration"] #[doc = "     data: [u8; 0],"] #[doc = " }"] #[doc = ""] #[doc = " Args are just an array of strings that represent command line arguments."] #[doc = " They are a sequence of the form:"] #[doc = ""] #[doc = "      (u16 /* val_len */ [0u8; val_len as usize])"] use core :: slice ; use crate :: ffi :: OsString ; #[doc = " Magic number indicating we have an environment block"] const ENV_MAGIC : [u8 ; 4] = * b"EnvB" ; #[doc = " Command line arguments list"] const ARGS_MAGIC : [u8 ; 4] = * b"ArgL" ; #[doc = " Magic number indicating the loader has passed application parameters"] const PARAMS_MAGIC : [u8 ; 4] = * b"AppP" ; #[cfg (test)] mod tests ; pub (crate) struct ApplicationParameters { data : & 'static [u8] , offset : usize , _entries : usize , } impl ApplicationParameters { pub (crate) unsafe fn new_from_ptr (data : * const u8) -> Option < ApplicationParameters > { if data . is_null () { return None ; } let magic = unsafe { core :: slice :: from_raw_parts (data , 4) } ; let block_length = unsafe { u32 :: from_le_bytes (slice :: from_raw_parts (data . add (4) , 4) . try_into () . ok () ?) as usize } ; let data_length = unsafe { u32 :: from_le_bytes (slice :: from_raw_parts (data . add (8) , 4) . try_into () . ok () ?) as usize } ; let entries = unsafe { u32 :: from_le_bytes (slice :: from_raw_parts (data . add (12) , 4) . try_into () . ok () ?) as usize } ; if data_length < 16 || magic != PARAMS_MAGIC || block_length != 8 { return None ; } let data = unsafe { slice :: from_raw_parts (data , data_length) } ; Some (ApplicationParameters { data , offset : 0 , _entries : entries }) } } impl Iterator for ApplicationParameters { type Item = ApplicationParameter ; fn next (& mut self) -> Option < Self :: Item > { if self . offset + 4 > self . data . len () { return None ; } let magic = & self . data [self . offset .. self . offset + 4] ; self . offset += 4 ; if self . offset + 4 > self . data . len () { return None ; } let size = u32 :: from_le_bytes (self . data [self . offset .. self . offset + 4] . try_into () . unwrap ()) as usize ; self . offset += 4 ; if self . offset + size > self . data . len () { return None ; } let data = & self . data [self . offset .. self . offset + size] ; self . offset += size ; Some (ApplicationParameter { data , magic : magic . try_into () . unwrap () }) } } pub (crate) struct ApplicationParameter { data : & 'static [u8] , magic : [u8 ; 4] , } pub (crate) struct ApplicationParameterError ; pub (crate) struct EnvironmentBlock { _count : usize , data : & 'static [u8] , offset : usize , } impl TryFrom < & ApplicationParameter > for EnvironmentBlock { type Error = ApplicationParameterError ; fn try_from (value : & ApplicationParameter) -> Result < Self , Self :: Error > { if value . data . len () < 2 || value . magic != ENV_MAGIC { return Err (ApplicationParameterError) ; } let count = u16 :: from_le_bytes (value . data [0 .. 2] . try_into () . unwrap ()) as usize ; Ok (EnvironmentBlock { data : & value . data [2 ..] , offset : 0 , _count : count }) } } pub (crate) struct EnvironmentEntry { pub key : & 'static str , pub value : & 'static str , } impl Iterator for EnvironmentBlock { type Item = EnvironmentEntry ; fn next (& mut self) -> Option < Self :: Item > { if self . offset + 2 > self . data . len () { return None ; } let key_len = u16 :: from_le_bytes (self . data [self . offset .. self . offset + 2] . try_into () . ok () ?) as usize ; self . offset += 2 ; if self . offset + key_len > self . data . len () { return None ; } let key = core :: str :: from_utf8 (& self . data [self . offset .. self . offset + key_len]) . ok () ? ; self . offset += key_len ; if self . offset + 2 > self . data . len () { return None ; } let value_len = u16 :: from_le_bytes (self . data [self . offset .. self . offset + 2] . try_into () . ok () ?) as usize ; self . offset += 2 ; if self . offset + value_len > self . data . len () { return None ; } let value = core :: str :: from_utf8 (& self . data [self . offset .. self . offset + value_len]) . ok () ? ; self . offset += value_len ; Some (EnvironmentEntry { key , value }) } } pub (crate) struct ArgumentList { data : & 'static [u8] , _count : usize , offset : usize , } impl TryFrom < & ApplicationParameter > for ArgumentList { type Error = ApplicationParameterError ; fn try_from (value : & ApplicationParameter) -> Result < Self , Self :: Error > { if value . data . len () < 2 || value . magic != ARGS_MAGIC { return Err (ApplicationParameterError) ; } let count = u16 :: from_le_bytes (value . data [0 .. 2] . try_into () . or (Err (ApplicationParameterError)) ?) as usize ; Ok (ArgumentList { data : & value . data [2 ..] , _count : count , offset : 0 }) } } pub (crate) struct ArgumentEntry { value : & 'static str , } impl Into < & str > for ArgumentEntry { fn into (self) -> & 'static str { self . value } } impl Into < OsString > for ArgumentEntry { fn into (self) -> OsString { self . value . into () } } impl Iterator for ArgumentList { type Item = ArgumentEntry ; fn next (& mut self) -> Option < Self :: Item > { if self . offset + 2 > self . data . len () { return None ; } let value_len = u16 :: from_le_bytes (self . data [self . offset .. self . offset + 2] . try_into () . ok () ?) as usize ; self . offset += 2 ; if self . offset + value_len > self . data . len () { return None ; } let value = core :: str :: from_utf8 (& self . data [self . offset .. self . offset + value_len]) . ok () ? ; self . offset += value_len ; Some (ArgumentEntry { value }) } }